// radar: um painel lateral com o que o agente está fazendo, ao vivo.
// Demonstra: Pane aberto por comando, atoms que redesenham sozinhos, timer e turn.complete.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { CallRow } from '../types'
import {
  addUsage,
  bar,
  colorOf,
  countCall,
  EMPTY_TOTALS,
  formatMs,
  formatTokens,
  running,
  speedColor,
  SPINNER,
  summarize,
  sumTotal,
  toolCounts,
  toolLabel,
  topFiles,
} from './lib'

type $ = EngineInterface

const PANE = 'radar'
const calls = atom({ plugin: 'radar', key: 'calls' } as const, [])
const totals = atom({ plugin: 'radar', key: 'totals' } as const, EMPTY_TOTALS)
const now = atom({ plugin: 'radar', key: 'now' } as const, 0)

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`

async function openRadar($: $): Promise<void> {
  await $.ui.open({ id: PANE, title: 'Radar', closeOnEscape: true })
}

/** Só escreve (e redesenha) quando há ferramenta rodando: é o cronômetro e o spinner do "agora". */
async function tick($: $): Promise<void> {
  if (running(await read($, calls)) !== undefined) {
    const time = await $.clock.now()
    await update($, now, () => time)
  }
}

export const register: Register = (on, options) => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'radar',
      description: 'Abre o painel com o que o agente está fazendo agora',
      argumentHint: '[fechar|limpar]',
    })
    $.clock.every(250, () => void tick($))
    if (options.abrirAoIniciar === true) void openRadar($)

    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const input = e as unknown as Record<string, unknown>
    const row: CallRow = {
      id: e.tool_use_id ?? `${e.tool}-${await $.clock.now()}`,
      tool: e.tool,
      summary: summarize(e.tool, input),
      startedAt: await $.clock.now(),
      ms: null,
      isOk: null,
      isSubagent: e.agentId !== undefined,
    }
    // Guarda só as 100 últimas: o painel nunca mostra mais que isso.
    await update($, calls, list => [...list, row].slice(-100))
    await update($, totals, t => countCall(t, e.tool, input))

    const ran = await next(e)

    const ms = (await $.clock.now()) - row.startedAt
    const isOk = ran.deny === undefined && ran.isError !== true
    await update($, calls, list => list.map(one => (one.id === row.id ? { ...one, ms, isOk } : one)))

    return ran
  })

  // Os tokens vêm prontos no fim de cada turno, do agente principal e dos subagentes.
  on('turn.complete', async ($, e, next) => {
    const usage = e.usage
    if (usage !== undefined) await update($, totals, t => ({ ...t, tokens: addUsage(t.tokens, usage) }))

    return next(e)
  })

  on('command.run', { command: 'radar' }, async ($, e) => {
    const action = e.args.trim()
    if (action === 'fechar') {
      await $.ui.close({ id: PANE })
      return { text: 'Radar fechado.' }
    }
    if (action === 'limpar') {
      await update($, calls, () => [])
      await update($, totals, () => EMPTY_TOTALS)
    }
    await openRadar($)

    return { text: 'Radar aberto.' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const list = await read($, calls)
    const t = await read($, totals)
    const time = await read($, now)
    const current = running(list)
    const elapsed = current === undefined ? 0 : Math.max(0, time - current.startedAt)

    // O tamanho do corpo do painel: a lista e as barras se ajustam a ele.
    const height = e.props.scroll?.bodyRows ?? (e.viewport?.rows ?? 24) - 4
    const width = e.props.bodyColumns ?? 60
    const files = topFiles(t, Math.min(5, Math.max(0, height - 26)))
    const tools = toolCounts(t, 5)
    const recent = list.slice(-Math.max(3, height - 16 - files.length - tools.length))
    const top = tools[0]?.[1] ?? 1

    // Um título de seção: nome em destaque e uma régua até a borda.
    const section = (title: string, extra = '') => (
      <Box marginTop={1}>
        <Text color="claude" bold>
          {title}
        </Text>
        <Text color="gray">{extra === '' ? '' : `  ${extra}`}</Text>
      </Box>
    )

    return (
      // O painel do Claude Code tem fundo cinza; a cor 0 da paleta é o fundo do próprio terminal.
      <Box flexDirection="column" backgroundColor="ansi256(0)" minHeight={height} paddingX={1}>
        <Box justifyContent="space-between">
          <Text color="claude" bold>
            ◉ RADAR
          </Text>
          {current === undefined ? (
            <Text color="gray">○ ocioso</Text>
          ) : (
            <Text color="green" bold>
              ● ao vivo
            </Text>
          )}
        </Box>

        {section('AGORA')}
        {current === undefined ? (
          <Text color="gray">  esperando o próximo passo do agente</Text>
        ) : (
          <Box gap={1}>
            <Text color="yellow">{` ${SPINNER[Math.floor(time / 250) % SPINNER.length]}`}</Text>
            <Text color={colorOf(current.tool)} bold>
              {toolLabel(current.tool)}
            </Text>
            <Box flexGrow={1}>
              <Text color="whiteBright" wrap="truncate-end">
                {current.summary}
              </Text>
            </Box>
            <Text color={speedColor(elapsed)} bold>
              {formatMs(elapsed)}
            </Text>
          </Box>
        )}

        {section('ÚLTIMAS CHAMADAS', list.length === 0 ? '' : `${sumTotal(t)} na sessão`)}
        {list.length === 0 && <Text color="gray">  nenhuma ainda</Text>}
        {recent.map(call => (
          <Box key={call.id} gap={1}>
            <Text color={call.isOk === null ? 'yellow' : call.isOk ? 'green' : 'red'} bold>
              {call.isOk === null ? ' …' : call.isOk ? ' ✓' : ' ✗'}
            </Text>
            <Text color={colorOf(call.tool)}>{toolLabel(call.tool)}</Text>
            <Box flexGrow={1}>
              <Text color={call.isSubagent ? 'gray' : 'whiteBright'} wrap="truncate-end">
                {call.isSubagent ? '↳ ' : ''}
                {call.summary}
              </Text>
            </Box>
            <Text color={call.ms === null ? 'gray' : speedColor(call.ms)}>{call.ms === null ? '' : formatMs(call.ms)}</Text>
          </Box>
        ))}

        {tools.length > 0 && section('FERRAMENTAS')}
        {tools.map(([tool, count]) => (
          <Box key={tool} gap={1}>
            <Text color={colorOf(tool)}>{` ${toolLabel(tool)}`}</Text>
            <Text color={colorOf(tool)}>{bar(count, top, Math.max(4, Math.min(24, width - 16)))}</Text>
            <Text color="whiteBright" bold>
              {count}
            </Text>
          </Box>
        ))}

        {files.length > 0 && section('ARQUIVOS', `${plural(Object.keys(t.read).length, 'lido')} · ${plural(Object.keys(t.edited).length, 'editado')}`)}
        {files.map(file => (
          <Box key={file.path} gap={1}>
            <Box flexGrow={1}>
              <Text color="whiteBright" wrap="truncate-start">{` ${file.path}`}</Text>
            </Box>
            <Text color="cyan">{file.reads > 0 ? `${file.reads}× lido` : ''}</Text>
            <Text color="magenta">{file.edits > 0 ? `${file.edits}× editado` : ''}</Text>
          </Box>
        ))}

        {section('TOKENS')}
        <Box gap={2}>
          <Text color="gray">
            {' entrada '}
            <Text color="whiteBright" bold>
              {formatTokens(t.tokens.input)}
            </Text>
          </Text>
          <Text color="gray">
            {'saída '}
            <Text color="whiteBright" bold>
              {formatTokens(t.tokens.output)}
            </Text>
          </Text>
          <Text color="gray">
            {'cache '}
            <Text color="green" bold>
              {formatTokens(t.tokens.cacheRead)}
            </Text>
          </Text>
        </Box>

        <Box gap={2} marginTop={1}>
          <Button
            key="clear"
            label="Limpar"
            onPress={async () => {
              await update($, calls, () => [])
              await update($, totals, () => EMPTY_TOTALS)
            }}
          />
          <Button key="close" label="Fechar" role="dismiss" onPress={() => $.ui.close({ id: PANE })} />
        </Box>
      </Box>
    )
  })
}

