// Lógica pura do radar: resumir cada chamada e somar os contadores. Sem `$`, para testar fácil.

import type { CallRow, Tokens, Totals } from '../types'

export const EMPTY_TOTALS: Totals = {
  byTool: {},
  read: {},
  edited: {},
  tokens: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
}

// Cada família de ferramenta tem uma cor: dá para "ler" o painel de longe, só pelas cores.
const COLORS: Record<string, string> = {
  Read: 'cyan',
  Edit: 'magenta',
  Write: 'magenta',
  NotebookEdit: 'magenta',
  Bash: 'yellow',
  Grep: 'blue',
  Glob: 'blue',
  WebFetch: 'greenBright',
  WebSearch: 'greenBright',
  Agent: 'green',
}

export function colorOf(tool: string): string {
  return COLORS[tool] ?? 'white'
}

/** O nome curto, com largura fixa para as colunas alinharem: "mcp__itsaplan__get_issue" vira "mcp:itsaplan". */
export function toolLabel(tool: string, width = 6): string {
  const name = tool.replace(/^mcp__([\w-]+?)__.*/, 'mcp:$1')

  return name.length > width ? `${name.slice(0, width - 1)}…` : name.padEnd(width)
}

/** Verde rápido, amarelo médio, vermelho lento. */
export function speedColor(ms: number): string {
  return ms < 1_000 ? 'green' : ms < 5_000 ? 'yellow' : 'red'
}

export const SPINNER = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']

/** Uma barra proporcional: `count` de `max` ocupa até `width` blocos (sempre ao menos um). */
export function bar(count: number, max: number, width: number): string {
  return '█'.repeat(Math.max(1, Math.round((count / Math.max(1, max)) * width)))
}

/** As ferramentas mais usadas, da mais para a menos. */
export function toolCounts(totals: Totals, n = 5): [string, number][] {
  return Object.entries(totals.byTool)
    .sort((a, b) => b[1] - a[1])
    .slice(0, n)
}

/** Os três últimos pedaços do caminho: o bastante para reconhecer o arquivo. */
export function shortPath(path: unknown): string {
  return String(path ?? '').split('/').filter(Boolean).slice(-3).join('/')
}

function clip(text: string, max: number): string {
  const line = text.split('\n')[0]?.trim() ?? ''

  return line.length > max ? `${line.slice(0, max - 1)}…` : line
}

/** O essencial do input de cada ferramenta, em uma linha. */
export function summarize(tool: string, input: Record<string, unknown>): string {
  switch (tool) {
    case 'Read':
    case 'Edit':
    case 'Write':
      return shortPath(input.file_path)
    case 'NotebookEdit':
      return shortPath(input.notebook_path)
    case 'Bash':
      return clip(String(input.command ?? ''), 60)
    case 'Grep':
      return `/${clip(String(input.pattern ?? ''), 40)}/${input.path === undefined ? '' : ` em ${shortPath(input.path)}`}`
    case 'Glob':
      return clip(String(input.pattern ?? ''), 50)
    case 'WebFetch':
      return clip(String(input.url ?? '').replace(/^https?:\/\//, ''), 50)
    case 'WebSearch':
      return clip(String(input.query ?? ''), 50)
    case 'Agent':
      return clip(String(input.description ?? input.prompt ?? ''), 50)
    default:
      return tool.replace(/^mcp__/, '').replace(/__/g, ' › ')
  }
}

function bump(counts: Record<string, number>, key: string): Record<string, number> {
  return { ...counts, [key]: (counts[key] ?? 0) + 1 }
}

/** Soma uma chamada aos contadores: por ferramenta e, quando há arquivo, lido ou editado. */
export function countCall(totals: Totals, tool: string, input: Record<string, unknown>): Totals {
  const file = shortPath(input.file_path ?? input.notebook_path)
  const isEdit = tool === 'Edit' || tool === 'Write' || tool === 'NotebookEdit'

  return {
    ...totals,
    byTool: bump(totals.byTool, tool),
    read: tool === 'Read' && file !== '' ? bump(totals.read, file) : totals.read,
    edited: isEdit && file !== '' ? bump(totals.edited, file) : totals.edited,
  }
}

type Usage = { input_tokens: number; output_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number }

export function addUsage(tokens: Tokens, usage: Usage): Tokens {
  return {
    input: tokens.input + usage.input_tokens,
    output: tokens.output + usage.output_tokens,
    cacheRead: tokens.cacheRead + usage.cache_read_input_tokens,
    cacheWrite: tokens.cacheWrite + usage.cache_creation_input_tokens,
  }
}

/** Os arquivos mais tocados, somando leituras e edições. */
export function topFiles(totals: Totals, n: number): { path: string; reads: number; edits: number }[] {
  const paths = new Set([...Object.keys(totals.read), ...Object.keys(totals.edited)])

  return [...paths]
    .map(path => ({ path, reads: totals.read[path] ?? 0, edits: totals.edited[path] ?? 0 }))
    .sort((a, b) => b.reads + b.edits - (a.reads + a.edits) || b.edits - a.edits)
    .slice(0, n)
}

export function formatMs(ms: number): string {
  if (ms < 1_000) return `${Math.round(ms)}ms`
  if (ms < 60_000) return `${(ms / 1_000).toFixed(1).replace('.', ',')}s`
  const seconds = Math.round(ms / 1_000)

  return `${Math.floor(seconds / 60)}min ${String(seconds % 60).padStart(2, '0')}s`
}

export function formatTokens(n: number): string {
  if (n < 1_000) return String(n)
  if (n < 1_000_000) return `${(n / 1_000).toFixed(1).replace('.', ',').replace(',0', '')} mil`

  return `${(n / 1_000_000).toFixed(1).replace('.', ',').replace(',0', '')} mi`
}

export function sumTotal(totals: Totals): number {
  return Object.values(totals.byTool).reduce((sum, count) => sum + count, 0)
}

/** A chamada mais antiga ainda rodando, para o "agora". */
export function running(calls: readonly CallRow[]): CallRow | undefined {
  return calls.find(call => call.ms === null)
}

