/** Uma chamada de ferramenta como o radar a mostra. */
export type CallRow = {
  id: string
  tool: string
  /** O essencial do input: caminho, comando, padrão de busca. */
  summary: string
  startedAt: number
  /** Duração; null enquanto roda. */
  ms: number | null
  /** ✓ ou ✗; null enquanto roda. */
  isOk: boolean | null
  /** Chamada feita por um subagente, não pelo agente principal. */
  isSubagent: boolean
}

export type Tokens = { input: number; output: number; cacheRead: number; cacheWrite: number }

/** Os contadores da sessão. */
export type Totals = {
  byTool: Record<string, number>
  read: Record<string, number>
  edited: Record<string, number>
  tokens: Tokens
}

declare module 'claude-code' {
  interface PluginState {
    radar: {
      calls: CallRow[]
      totals: Totals
      /** A hora do último tique: faz o cronômetro da ferramenta em execução andar. */
      now: number
    }
  }
}
